"""A cyclic subgroup of order m in the group generated by the input graph’s edge transpositions implies that the input graph contains a cycle of length m."""

import itertools
import json

RECORD_ID = "arxiv_2503.11238v2__source_enriched_codex"
OUTCOME = "WITNESS_FOUND"
WITNESS_DESCRIPTION = (
    "For m = 3, take the labeled simple graph with vertices {0,1,2} and edges "
    "{{0,1},{0,2}}. Its edge transpositions generate the 3-cycle (0 2 1), so "
    "they generate a cyclic subgroup of order 3, but the graph has no cycle "
    "of length 3."
)
REFUTATION_EXPLANATION = (
    "Under right-to-left composition, (0 1) composed with (0 2) is the "
    "permutation (0 2 1), which has order 3. Thus the generated group contains "
    "its cyclic subgroup of order 3. The graph has only two edges and lacks "
    "the edge {1,2}, so it contains no 3-cycle; this falsifies the implication "
    "at m = 3."
)
SEARCH_SPACE = (
    "All 8 labeled simple undirected graphs on the fixed vertex set {0,1,2}, "
    "with m fixed to 3. For each graph, the complete permutation group generated "
    "by its edge transpositions was enumerated, every group element was tested "
    "for order 3, and every ordered triple of distinct vertices was tested for "
    "a graph cycle of length 3."
)


def compose(left, right):
    return tuple(left[right[index]] for index in range(len(left)))


def transposition(size, first, second):
    permutation = list(range(size))
    permutation[first], permutation[second] = (
        permutation[second],
        permutation[first],
    )
    return tuple(permutation)


def generated_group(size, edges):
    identity = tuple(range(size))
    generators = [transposition(size, first, second) for first, second in edges]
    elements = [identity]
    seen = {identity}
    position = 0
    while position < len(elements):
        current = elements[position]
        position += 1
        for generator in generators:
            candidate = compose(current, generator)
            if candidate not in seen:
                seen.add(candidate)
                elements.append(candidate)
    return tuple(elements)


def factorial(number):
    result = 1
    for factor in range(2, number + 1):
        result *= factor
    return result


def permutation_order(permutation):
    identity = tuple(range(len(permutation)))
    power = identity
    for exponent in range(1, factorial(len(permutation)) + 1):
        power = compose(permutation, power)
        if power == identity:
            return exponent
    raise AssertionError("A permutation order must divide the finite group size")


def has_cycle_of_length(vertices, edges, length):
    edge_set = {frozenset(edge) for edge in edges}
    for cycle in itertools.permutations(vertices, length):
        valid = True
        for index in range(length):
            edge = frozenset((cycle[index], cycle[(index + 1) % length]))
            if edge not in edge_set:
                valid = False
                break
        if valid:
            return True
    return False


def main():
    vertices = (0, 1, 2)
    possible_edges = ((0, 1), (0, 2), (1, 2))
    length = 3
    counterexamples = []

    for mask in range(1 << len(possible_edges)):
        edges = tuple(
            edge
            for index, edge in enumerate(possible_edges)
            if mask & (1 << index)
        )
        group = generated_group(len(vertices), edges)
        order_three_elements = tuple(
            permutation
            for permutation in group
            if permutation_order(permutation) == length
        )
        graph_has_cycle = has_cycle_of_length(vertices, edges, length)
        if order_three_elements and not graph_has_cycle:
            counterexamples.append((mask, edges, order_three_elements))

    expected_edges = ((0, 1), (0, 2))
    expected_cycle = (2, 0, 1)
    assert counterexamples
    assert counterexamples[0][0] == 3
    assert counterexamples[0][1] == expected_edges
    assert expected_cycle in counterexamples[0][2]

    result = {
        "record_id": RECORD_ID,
        "outcome": OUTCOME,
        "witness_description": WITNESS_DESCRIPTION,
        "refutation_explanation": REFUTATION_EXPLANATION,
        "search_space": SEARCH_SPACE,
    }
    print(json.dumps(result, sort_keys=True, separators=(",", ":")))


if __name__ == "__main__":
    main()
